#include "ScratchKnob.h"
#include <cmath>
ScratchKnob::ScratchKnob(ScratchPadAudioProcessor& p):processor(p),parameter(*p.apvts.getParameter("scratchAmount")){attachment=std::make_unique<juce::ParameterAttachment>(parameter,[this](float f){value=f;repaint();},nullptr);attachment->sendInitialUpdate();setMouseCursor(juce::MouseCursor::PointingHandCursor);}
void ScratchKnob::paint(juce::Graphics& g){auto b=getLocalBounds().toFloat();float d=std::min(b.getWidth(),b.getHeight()-17),r=d*.46f;auto c=juce::Point<float>(b.getCentreX(),d*.49f);for(int i=0;i<6;++i){float start=juce::degreesToRadians(-225.f+i*45.f),end=start+juce::MathConstants<float>::pi/4;juce::Path wedge;wedge.addCentredArc(c.x,c.y,r,r,0,start+.026f,end-.026f,true);wedge.lineTo(c);wedge.closeSubPath();g.setColour(i<value*6/100?Theme::red:Theme::darkRed);g.fillPath(wedge);g.setColour(Theme::cyan.withAlpha(.75f));float x=c.x+std::sin(start)*r,y=c.y-std::cos(start)*r;g.drawLine(c.x,c.y,x,y,.8f);}g.setColour(Theme::bg);g.fillEllipse(c.x-r*.52f,c.y-r*.52f,r*1.04f,r*1.04f);g.setColour(Theme::cyan);juce::Path logo;logo.startNewSubPath(c.x-r*.31f,c.y);logo.lineTo(c.x+r*.29f,c.y);logo.lineTo(c.x+r*.14f,c.y-r*.14f);logo.startNewSubPath(c.x+r*.29f,c.y);logo.lineTo(c.x+r*.14f,c.y+r*.14f);logo.startNewSubPath(c.x+r*.24f,c.y-r*.25f);logo.lineTo(c.x-r*.24f,c.y+r*.25f);logo.lineTo(c.x-r*.12f,c.y+r*.24f);g.strokePath(logo,juce::PathStrokeType(2.3f));g.setFont(Theme::font(15,true));g.setColour(Theme::light);g.drawFittedText("SCRATCH",0,(int)d+2,getWidth(),17,juce::Justification::centred,1);}
void ScratchKnob::change(float f){attachment->setValueAsPartOfGesture(juce::jlimit(0.f,100.f,f));}
void ScratchKnob::mouseDown(const juce::MouseEvent& e){startY=e.y;dragValue=value;attachment->beginGesture();}
void ScratchKnob::mouseDrag(const juce::MouseEvent& e){change(dragValue+(startY-e.y)*.8f);}
void ScratchKnob::mouseUp(const juce::MouseEvent&){attachment->endGesture();}
void ScratchKnob::mouseDoubleClick(const juce::MouseEvent&){attachment->setValueAsCompleteGesture(100);}
